import{_ as t,o as a,c as p,a3 as o}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xuehui-tiwen/109-刻板印象.md","filePath":"books/xuehui-tiwen/109-刻板印象.md","lastUpdated":1794316978000}'),_={name:"books/xuehui-tiwen/109-刻板印象.md"};function r(s,e,n,i,d,c){return a(),p("div",null,[...e[0]||(e[0]=[o('<h2 id="刻板印象" tabindex="-1">刻板印象 <a class="header-anchor" href="#刻板印象" aria-label="Permalink to &quot;刻板印象&quot;">​</a></h2><p>在我们接触任何主题之前，我们都带有一定的信念或思维习惯。当我们形成刻板印象时，我们就会断言，因为某个人是特定集体中的一员，所以他肯定具有一系列明确的特征。</p><p>刻板印象会拙劣地取代“慢思考”。下面，我们举几个小例子：</p><p>1）有面部毛发的男人都很睿智。</p><p>2）胖子活得都很快乐。</p><p>3）日本人都很勤劳。</p><p>4）年轻人办事比较草率。</p><p>5）女人最适合做秘书工作。</p><p>6）领取社会福利的人都比较懒惰。</p><p>上述6个例子都在假装告诉你特定类型的人的某些重要特征。如果我们相信这些刻板印象，我们就会失去强势批判性思维所需的开放、包容的精神，从而难以持开放的态度去接触这些人和他们的思想。此外，一旦某一问题或争端牵涉这些人，我们心里马上就有了成见。那些刻板印象一定会提前介入，抢在理性分析之前占据先机。</p><p>每个人都值得我们尊重，每个人所提出的论点都值得我们加以注意。刻板印象之所以会挡住批判性思维的道，是因为它们总是让人试图绕开客观评价的艰难过程。要成为一名批判性思维者，我们要成为充满好奇心和开放心态的表率，而刻板印象会阻断我们的道路，让我们无法仔细考虑别人所说的话。它总是早早关闭我们的思维，导致我们忽略有价值的信息。</p>',11)])])}const h=t(_,[["render",r]]);export{u as __pageData,h as default};
